#include <stdio.h>

int main(void) {
    unsigned int x = 23;
    printf("x << 1 = %u\n", x << 1);   // 23 * 2
    printf("x << 3 = %u\n", x << 3);   // 23 * 8
    printf("x >> 1 = %u\n", x >> 1);   // 23 / 2, fraction dropped
    printf("x >> 2 = %u\n", x >> 2);   // 23 / 4, fraction dropped
    printf("x      = %u\n", x);        // x itself is unchanged
