#include <stdio.h>

int main(void) {
    unsigned int color = 0x3366CC;           // red 0x33, green 0x66, blue 0xCC
    unsigned int red   = (color >> 16) & 0xFF;
    unsigned int green = (color >> 8) & 0xFF;
    unsigned int blue  = color & 0xFF;
    printf("red %u, green %u, blue %u\n", red, green, blue);

    unsigned int packed = (red << 16) | (green << 8) | blue;
    printf("packed again: 0x%06X\n", packed);
