}

#include <stdio.h>

int main(void) {
    unsigned int mode = 0754;              // leading 0: an octal literal
    unsigned int user  = (mode >> 6) & 07;
    unsigned int group = (mode >> 3) & 07;
    unsigned int other = mode & 07;
    printf("user %u, group %u, other %u\n", user, group, other);

    if (mode & 0004) {                     // test one bit: other read
        printf("others may read\n");
    }
    if ((mode & 0002) == 0) {              // other write
        printf("others may not write\n");
    }

    // like chmod g=w: clear the 3 group bits, then put 2 (w) there
    mode = (mode & ~(07u << 3)) | (2u << 3);
    printf("new mode %o\n", mode);
    return 0;
}

#include <stdint.h>
#include <stdio.h>

void printb(uint8_t x) {
    char buf[9];
    for (size_t i = 0; i < 8; i++) {
        uint8_t y = x & (1 << i);          // keep only bit i
        buf[7 - i] = (y > 0) ? '1' : '0';  // bit 0 goes at the right end
    }
    buf[8] = '\0';
    printf("%s\n", buf);
}

int main(void) {
    printb(18);
    printb(255);
    printb(128);
    return 0;
}

