#include <stdio.h>

// returns x with its len bits starting at bit pos replaced by value
unsigned int setfield(unsigned int x, unsigned int pos, unsigned int len, unsigned int value) {
    unsigned int mask = (1u << len) - 1;      // len ones at the right
    x = x & ~(mask << pos);                   // 1. clear the field
    x = x | ((value & mask) << pos);          // 2. put the new value there
    return x;
}

int main(void) {
    printf("%o\n", setfield(0754, 3, 3, 2));          // group bits become w only
    printf("%X\n", setfield(0x3366CC, 8, 8, 0xFF));   // green becomes FF
    printf("%u\n", setfield(0, 0, 4, 9));             // 0 with 9 in the low 4 bits
    return 0;
}

