#include <math.h>
#include <stdio.h>

// counts the elements of a that are within tol of target
size_t count_near(const double a[], size_t n, double target, double tol) {
    size_t count = 0;
    for (size_t i = 0; i < n; i++) {
        if (fabs(a[i] - target) <= tol) {
            count++;
        }
    }
    return count;
}

int main(void) {
    double a[5] = {0.1 + 0.2, 0.3, 0.30001, 3 * 0.1, 1.0};
    size_t exact = 0;
    for (size_t i = 0; i < 5; i++) {
        if (a[i] == 0.3) {
            exact++;
        }
    }
    printf("== 0.3: %zu\n", exact);
    printf("near 0.3: %zu\n", count_near(a, 5, 0.3, 1e-9));
    return 0;
}

#include <stdio.h>

// prints mode's 9 permission bits like ls -l, e.g. 0754 prints rwxr-xr--
void print_perms(unsigned int mode) {
    char letters[] = "rwxrwxrwx";
    for (int i = 8; i >= 0; i--) {             // bit 8 (0400) down to bit 0 (0001)
        if ((mode >> i) & 1u) {
            printf("%c", letters[8 - i]);
        } else {
            printf("-");
        }
    }
    printf("\n");
}

int main(void) {
    print_perms(0754);
    print_perms(0640);
    print_perms(0);
    return 0;
}
